import React, { useState, useEffect } from 'react';
import './header.css';
import { FaBars, FaTimes, FaPhoneAlt, FaEnvelope, FaStar, FaChevronDown, FaChevronRight } from 'react-icons/fa';
import { FaArrowRight } from "react-icons/fa";
import { Link } from 'gatsby';
import { BUSINESS, NAV, SERVICES } from '../../content';
import logo from '../../images/logo.jpg';

interface SubmenuItem {
  name: string;
  href: string;
}

interface NavLink {
  name: string;
  href: string;
  submenu?: SubmenuItem[];
}

const Header: React.FC = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isTopBarVisible, setIsTopBarVisible] = useState(true);
  const [isScrolled, setIsScrolled] = useState(false);
  const [lastScrollY, setLastScrollY] = useState(0);
  const [isMobileServicesOpen, setIsMobileServicesOpen] = useState(false);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
    if (!isMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
  };

  const closeMenu = () => {
    setIsMenuOpen(false);
    document.body.style.overflow = 'unset';
  };

  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;
      if (currentScrollY > 100) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }

      if (currentScrollY > 80 && currentScrollY > lastScrollY) {
        setIsTopBarVisible(false);
      } else {
        setIsTopBarVisible(true);
      }
      setLastScrollY(currentScrollY);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [lastScrollY]);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth > 768 && isMenuOpen) closeMenu();
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isMenuOpen]);

  useEffect(() => {
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, []);

  const navLinks: NavLink[] = [
    ...NAV.mainLinks.slice(0, 1),
    { 
      name: NAV.servicesLabel, 
      href: NAV.servicesHref,
      submenu: SERVICES.map(service => ({
        name: service.title,
        href: `/${service.slug}`
      }))
    },
    ...NAV.mainLinks.slice(1)
  ];

  return (
    <header className={`header ${isScrolled ? 'header-scrolled' : ''}`}>
      {/* Top Bar - hides on scroll down */}
      <div className={`top-bar ${!isTopBarVisible ? 'top-bar-hidden' : ''}`}>
        <div className="container">
          <div className="top-bar-content">
            <div className="contact-info">
              <a href={BUSINESS.phoneHref} className="contact-link">
                <FaPhoneAlt className="icon" />
                <span>{BUSINESS.phone}</span>
              </a>
              <span className="divider">|</span>
              <a href={BUSINESS.emailHref} className="contact-link">
                <FaEnvelope className="icon" />
                <span>{BUSINESS.email}</span>
              </a>
            </div>
            <div className="rating-info">
              <a
                href={BUSINESS.googleReviewUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="bbb-link"
              >
                <FaStar className="star-icon" />
                <span>{BUSINESS.reviewRating} ★ Google Reviews</span>
              </a>
            </div>
          </div>
        </div>
      </div>

      {/* Main Navigation */}
      <div className="main-nav">
        <div className="container">
          <div className="nav-wrapper">
            <div className="logo">
              <a href="/" className="logo-link" aria-label={BUSINESS.name}>
                <img src={logo} alt={BUSINESS.name} className="logo-img" />
              </a>
            </div>

            <nav className="desktop-nav">
              <ul className="nav-list">
                {navLinks.map((link) => (
                  <li key={link.name} className={link.submenu ? 'has-submenu' : ''}>
                    <a href={link.href} className="nav-link">
                      {link.name} {link.submenu && <FaChevronDown className="dropdown-icon" />}
                    </a>
                    {link.submenu && (
                      <div className="submenu">
                        <ul className="submenu-list">
                          {link.submenu.map((item) => (
                            <li key={item.name}>
                              <a href={item.href} className="submenu-link">
                                {item.name}
                              </a>
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </li>
                ))}
              </ul>
            </nav>

          <div className="cta-wrapper">
  <a href={BUSINESS.phoneHref} className="cta-button">
    <span className="cta-text">{NAV.ctaText}</span>
    <span className="cta-icon">
      <FaArrowRight />
    </span>
  </a>
</div>

            <button
              className="mobile-menu-button"
              onClick={toggleMenu}
              aria-label="Toggle menu"
              aria-expanded={isMenuOpen}
            >
              {isMenuOpen ? <FaTimes /> : <FaBars />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Slide‑in Menu */}
      <div className={`mobile-menu-overlay ${isMenuOpen ? 'mobile-menu-open' : ''}`}>
        <div className="mobile-menu-content">
          <div className="mobile-menu-header">
            <a href="/" className="mobile-menu-logo" onClick={closeMenu} aria-label={BUSINESS.name}>
              <img src={logo} alt={BUSINESS.name} />
            </a>
            <button className="mobile-close-button" onClick={closeMenu}>
              <FaTimes />
            </button>
          </div>
          <nav className="mobile-nav">
            <ul className="mobile-nav-list">
              {navLinks.map((link) => (
                <li key={link.name} className="mobile-nav-item">
                  <div className="mobile-nav-link-wrapper">
                    <a href={link.href} className="mobile-nav-link" onClick={!link.submenu ? closeMenu : undefined}>
                      {link.name}
                    </a>
                    {link.submenu && (
                      <button 
                        className={`submenu-toggle ${isMobileServicesOpen ? 'active' : ''}`}
                        onClick={() => setIsMobileServicesOpen(!isMobileServicesOpen)}
                      >
                        <FaChevronRight />
                      </button>
                    )}
                  </div>
                  
                  {link.submenu && (
                    <ul className={`mobile-submenu ${isMobileServicesOpen ? 'open' : ''}`}>
                      {link.submenu.map((item) => (
                        <li key={item.name}>
                          <a href={item.href} className="mobile-submenu-link" onClick={closeMenu}>
                            {item.name}
                          </a>
                        </li>
                      ))}
                    </ul>
                  )}
                </li>
              ))}
            </ul>
          </nav>
          <div className="mobile-cta-wrapper">
            <a href={BUSINESS.phoneHref} className="mobile-cta-button" onClick={closeMenu}>
              {NAV.ctaText}
            </a>
          </div>
          <div className="mobile-contact-info">
            <a href={BUSINESS.phoneHref} className="mobile-contact-link">
              <FaPhoneAlt /> {BUSINESS.phone}
            </a>
            <a href={BUSINESS.emailHref} className="mobile-contact-link">
              <FaEnvelope /> {BUSINESS.email}
            </a>
            <a
              href={BUSINESS.googleReviewUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="mobile-bbb-link"
            >
              <FaStar /> {BUSINESS.reviewRating} ★ Google Reviews
            </a>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;
